{{< core/modal }}
    {{$footer}}
        <button type="button" class="btn btn-secondary" data-action="cancel">{{#str}} cancel {{/str}}</button>
        <button type="button" class="btn btn-primary" data-action="save">{{#str}} savechanges {{/str}}</button>
    {{/footer}}
{{/ core/modal }}

{{< core/modal }}
    {{$footer}}
        <button type="button"
                class="btn btn-primary"
                data-context-id="{{contextid}}"
                data-action="save">

            {{#str}} save {{/str}}
            <span class="hidden" data-region="loading-icon-container">
                {{> core/loading }}
            </span>
        </button>
    {{/footer}}
{{/ core/modal }}

{{< core/modal }}
    {{$footer}}
        <button type="button" class="btn btn-primary" data-action="deleteone">{{#str}} deleteoneevent, core_calendar {{/str}}</button>
        <button type="button" class="btn btn-secondary" data-action="deleteall">{{#str}} deleteallevents, core_calendar {{/str}}</button>
        <button type="button" class="btn btn-secondary" data-action="cancel">{{#str}} cancel {{/str}}</button>
    {{/footer}}
{{/ core/modal }}

{{< core_course/coursecards }}
    {{$menu}}
        <div class="card-footer menu border-0 bg-white ms-auto p-2">
            {{> block_myoverview/course-action-menu }}
        </div>
    {{/menu}}
    {{$progress}}
        {{#hasprogress}}
            <div class="card-footer border-0 bg-white w-100">
                {{> block_myoverview/progress-bar}}
            </div>
        {{/hasprogress}}
    {{/progress}}
    {{$coursename}}
        <span class="multiline" title="{{fullname}}">
            <span class="visually-hidden">{{{fullname}}}</span>
            <span aria-hidden="true">
                {{#shortentext}}55, {{{fullname}}} {{/shortentext}}
            </span>
        </span>
    {{/coursename}}
    {{$coursecategory}}
        {{#showcoursecategory}}
            <span class="visually-hidden">
                {{#str}}aria:coursecategory, core_course{{/str}}
            </span>
            <span class="categoryname text-truncate">
                {{{coursecategory}}}
            </span>
        {{/showcoursecategory}}
    {{/coursecategory}}
{{/ core_course/coursecards }}

{{< core/modal }}
    {{$footer}}
        {{#candelete}}
            <button type="button" class="btn btn-secondary" data-action="delete">{{#str}} delete {{/str}}</button>
        {{/candelete}}
        {{#action.actionable}}
            <a href="{{action.url}}">{{{action.name}}}</a>
        {{/action.actionable}}
        {{^action.actionable}}
            {{#isactionevent}}
            <a href="{{url}}">{{#str}} gotoactivity, core_calendar {{/str}}</a>
            {{/isactionevent}}
        {{/action.actionable}}

        {{^isactionevent}}
            {{#canedit}}
                <button type="button" class="btn btn-primary" data-action="edit">{{#str}} edit {{/str}}</button>
            {{/canedit}}
        {{/isactionevent}}
    {{/footer}}
{{/ core/modal }}
